    switch (self) {
      case TsEvent_ConnectionStateChanged(newState: final newState):
        sse_encode_i_32(0, serializer);
        sse_encode_ts_connection_state(newState, serializer);
      case TsEvent_Connected(
        serverName: final serverName,
        welcomeMessage: final welcomeMessage,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(serverName, serializer);
        sse_encode_opt_String(welcomeMessage, serializer);
      case TsEvent_Disconnected(reason: final reason):
        sse_encode_i_32(2, serializer);
        sse_encode_String(reason, serializer);
      case TsEvent_ConnectionLost(reason: final reason):
        sse_encode_i_32(3, serializer);
        sse_encode_String(reason, serializer);
      case TsEvent_ChannelCreated(channelId: final channelId, name: final name):
        sse_encode_i_32(4, serializer);
        sse_encode_i_64(channelId, serializer);
        sse_encode_String(name, serializer);
      case TsEvent_ChannelDeleted(channelId: final channelId):
        sse_encode_i_32(5, serializer);
        sse_encode_i_64(channelId, serializer);
      case TsEvent_ChannelEdited(channelId: final channelId, name: final name):
        sse_encode_i_32(6, serializer);
        sse_encode_i_64(channelId, serializer);
        sse_encode_String(name, serializer);
      case TsEvent_ChannelJoined(channelId: final channelId, name: final name):
        sse_encode_i_32(7, serializer);
        sse_encode_i_64(channelId, serializer);
        sse_encode_String(name, serializer);
      case TsEvent_UserJoined(
        userId: final userId,
        nickname: final nickname,
        channelId: final channelId,
      ):
        sse_encode_i_32(8, serializer);
        sse_encode_u_16(userId, serializer);
        sse_encode_String(nickname, serializer);
        sse_encode_i_64(channelId, serializer);
      case TsEvent_UserLeft(
        userId: final userId,
        nickname: final nickname,
        reason: final reason,
      ):
        sse_encode_i_32(9, serializer);
        sse_encode_u_16(userId, serializer);
        sse_encode_String(nickname, serializer);
        sse_encode_String(reason, serializer);
      case TsEvent_UserMoved(
        userId: final userId,
        nickname: final nickname,
        fromChannel: final fromChannel,
        toChannel: final toChannel,
      ):
        sse_encode_i_32(10, serializer);
        sse_encode_u_16(userId, serializer);
        sse_encode_String(nickname, serializer);
        sse_encode_i_64(fromChannel, serializer);
        sse_encode_i_64(toChannel, serializer);
      case TsEvent_UserKickedFromChannel(
        userId: final userId,
        kickerId: final kickerId,
        reason: final reason,
      ):
        sse_encode_i_32(11, serializer);
        sse_encode_u_16(userId, serializer);
        sse_encode_u_16(kickerId, serializer);
        sse_encode_String(reason, serializer);
      case TsEvent_UserKickedFromServer(
        userId: final userId,
        kickerId: final kickerId,
        reason: final reason,
      ):
        sse_encode_i_32(12, serializer);
        sse_encode_u_16(userId, serializer);
        sse_encode_u_16(kickerId, serializer);
        sse_encode_String(reason, serializer);
      case TsEvent_UserBanned(
        userId: final userId,
        bannerId: final bannerId,
        reason: final reason,
      ):
        sse_encode_i_32(13, serializer);
        sse_encode_u_16(userId, serializer);
        sse_encode_u_16(bannerId, serializer);
        sse_encode_String(reason, serializer);
      case TsEvent_UserUpdated(userId: final userId, nickname: final nickname):
        sse_encode_i_32(14, serializer);
        sse_encode_u_16(userId, serializer);
        sse_encode_String(nickname, serializer);
      case TsEvent_TalkStatusStart(userId: final userId):
        sse_encode_i_32(15, serializer);
        sse_encode_u_16(userId, serializer);
      case TsEvent_TalkStatusStop(userId: final userId):
        sse_encode_i_32(16, serializer);
        sse_encode_u_16(userId, serializer);
      case TsEvent_TextMessage(
        senderId: final senderId,
        senderName: final senderName,
        message: final message,
        target: final target,
      ):
        sse_encode_i_32(17, serializer);
        sse_encode_u_16(senderId, serializer);
        sse_encode_String(senderName, serializer);
        sse_encode_String(message, serializer);
        sse_encode_ts_message_target(target, serializer);
      case TsEvent_Poked(
        pokerId: final pokerId,
        pokerName: final pokerName,
        message: final message,
      ):
        sse_encode_i_32(18, serializer);
        sse_encode_u_16(pokerId, serializer);
        sse_encode_String(pokerName, serializer);
        sse_encode_String(message, serializer);
      case TsEvent_CommandError(errorId: final errorId, message: final message):
        sse_encode_i_32(19, serializer);
        sse_encode_u_32(errorId, serializer);
        sse_encode_String(message, serializer);
      case TsEvent_ChannelPermissionsUpdated(
        channelId: final channelId,
        permissionHints: final permissionHints,
      ):
        sse_encode_i_32(20, serializer);
        sse_encode_i_64(channelId, serializer);
        sse_encode_i_64(permissionHints, serializer);
      case TsEvent_StreamsChanged(streams: final streams):
        sse_encode_i_32(21, serializer);
        sse_encode_list_ts_stream(streams, serializer);
      case TsEvent_StreamJoinResponse(
        ownerId: final ownerId,
        streamId: final streamId,
        accepted: final accepted,
        message: final message,
        offer: final offer,
      ):
        sse_encode_i_32(22, serializer);
        sse_encode_u_16(ownerId, serializer);
        sse_encode_String(streamId, serializer);
        sse_encode_bool(accepted, serializer);
        sse_encode_opt_String(message, serializer);
        sse_encode_opt_String(offer, serializer);
      case TsEvent_StreamSignaling(
        ownerId: final ownerId,
        streamId: final streamId,
        json: final json,
      ):
        sse_encode_i_32(23, serializer);
        sse_encode_u_16(ownerId, serializer);
        sse_encode_String(streamId, serializer);
        sse_encode_String(json, serializer);
      case TsEvent_StreamJoinRequest(
        viewerId: final viewerId,
        streamId: final streamId,
        isRemove: final isRemove,
      ):
        sse_encode_i_32(24, serializer);
        sse_encode_u_16(viewerId, serializer);
        sse_encode_String(streamId, serializer);
        sse_encode_bool(isRemove, serializer);
      case TsEvent_FileDownloaded(
        channelId: final channelId,
        path: final path,
        data: final data,
      ):
        sse_encode_i_32(25, serializer);
        sse_encode_i_64(channelId, serializer);
        sse_encode_String(path, serializer);
        sse_encode_list_prim_u_8_strict(data, serializer);
      case TsEvent_FileTransferFailed(path: final path, error: final error):
        sse_encode_i_32(26, serializer);
        sse_encode_String(path, serializer);
        sse_encode_String(error, serializer);
    }
  }

